// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette{value: 10 ether}();
    }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(c));
        ts = bound(ts, 1, type(uint48).max);

        // First call at time ts: succeeds on both P and M.
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call at the SAME timestamp ts: P must revert
        // (block.timestamp > pastBlockTime fails). General rule:
        // any call whose timestamp is not strictly greater than the
        // last accepted call's timestamp reverts.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertFalse(ok2);
    }
}
